using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public sealed class CapturedQuest {public string character="",id="",name="",batch="";}
public sealed class CaptureMark {public string guide="",step="",questId="",name="";}
public sealed class QuestCaptureBatch {public string id="",character="",date="";public int count;public List<CaptureMark> marks=new List<CaptureMark>();}
internal sealed class CaptureQuestChoice {public string Id="",Name="";public string Label {get{return Name+(Id==""?"":" · #"+Id);}}}
internal sealed class CaptureCatalogue {internal List<CaptureQuestChoice> Quests=new List<CaptureQuestChoice>();internal List<TougliDocument> Documents=new List<TougliDocument>();internal int Unreadable;}
internal static class QuestCaptureImport {
 internal static string Key(string name){return QuestInstructionIndex.NameKey(name);}
 internal static bool Same(string a,string an,string b,string bn){return !String.IsNullOrEmpty(a)&&!String.IsNullOrEmpty(b)?a==b:Key(an)==Key(bn);}
 internal static void Validate(Data data){var d=data.dofus;if(d.capturedQuests==null)d.capturedQuests=new List<CapturedQuest>();if(d.captureHistory==null)d.captureHistory=new List<QuestCaptureBatch>();if(d.capturedQuests.Count>60000||d.captureHistory.Count>30||d.capturedQuests.Any(q=>q==null||String.IsNullOrEmpty(q.character)||q.character.Length>100||String.IsNullOrWhiteSpace(q.name)||q.name.Length>500||q.id==null||q.id.Length>12||q.batch==null||q.batch.Length>40)||d.captureHistory.Any(b=>b==null||b.id==null||b.id.Length>40||b.character==null||b.character.Length>100||b.date==null||b.date.Length>50||b.marks==null||b.marks.Count>50000||b.marks.Any(m=>m==null||!TougliReader.ValidSlug(m.guide)||String.IsNullOrEmpty(m.step)||m.step.Length>200||m.questId==null||m.questId.Length>12||m.name==null||m.name.Length>500))||d.captureHistory.Sum(b=>b.marks.Count)>50000)throw new InvalidDataException("Historique des imports de quêtes invalide.");}
 internal static bool Done(Data d,string character,string id,string name){return d.dofus.capturedQuests.Any(q=>q.character==character&&Same(q.id,q.name,id,name));}
 internal static CaptureCatalogue Catalogue(Store store,DofusCharacter character){var result=new CaptureCatalogue();string folder=Path.Combine(store.Root,"TougliCache");if(Directory.Exists(folder))foreach(var file in Directory.EnumerateFiles(folder,"*.json").Take(2000)){string slug=Path.GetFileNameWithoutExtension(file);if(!TougliReader.ValidSlug(slug))continue;try{var raw=TougliReader.Cached(store,slug);if(GanymedeReader.IsGuide(slug))continue;var doc=TougliReader.Parse(raw,character);if(doc.Slug!=slug)throw new InvalidDataException("Guide inattendu");result.Documents.Add(doc);result.Quests.AddRange(doc.Steps.Where(s=>!String.IsNullOrEmpty(s.QuestId)&&s.CanComplete).Select(s=>new CaptureQuestChoice{Id=s.QuestId,Name=s.Title}));}catch{result.Unreadable++;}}
 var index=QuestInstructionIndex.Load(store);result.Unreadable+=index.Unreadable;result.Quests.AddRange(index.Items.Select(q=>new CaptureQuestChoice{Id=q.GameQuestId??"",Name=q.QuestName}));result.Quests=result.Quests.Where(q=>!String.IsNullOrWhiteSpace(q.Name)&&q.Name.Length<=500&&q.Id.Length<=12).GroupBy(q=>q.Id+"/"+Key(q.Name)).Select(g=>g.First()).ToList();var namedIds=new HashSet<string>(result.Quests.Where(q=>q.Id!="").Select(q=>Key(q.Name)));result.Quests.RemoveAll(q=>q.Id==""&&namedIds.Contains(Key(q.Name)));return result;}
 internal static List<CaptureQuestChoice> Exact(CaptureCatalogue c,string line){string key=Key(line.Trim().TrimStart('✓','✔','•','☑','-',' '));return c.Quests.Where(q=>Key(q.Name)==key).ToList();}
 internal static int Distance(string a,string b){if(Math.Abs(a.Length-b.Length)>3)return 99;var row=Enumerable.Range(0,b.Length+1).ToArray();for(int i=1;i<=a.Length;i++){int prev=row[0];row[0]=i;for(int j=1;j<=b.Length;j++){int old=row[j];row[j]=Math.Min(Math.Min(row[j]+1,row[j-1]+1),prev+(a[i-1]==b[j-1]?0:1));prev=old;}}return row[b.Length];}
 internal static List<CaptureQuestChoice> Suggestions(CaptureCatalogue c,string line){var key=Key(line);if(key.Length<5||key.Length>200)return new List<CaptureQuestChoice>();return c.Quests.Select(q=>new{q,n=Distance(Key(q.Name),key)}).Where(x=>x.n<=Math.Min(3,key.Length/5)).OrderBy(x=>x.n).Take(5).Select(x=>x.q).ToList();}
 internal static void Apply(Data data,TougliDocument doc,DofusCharacter c){if(doc==null||c==null)return;foreach(var step in doc.Steps.Where(s=>s.CanComplete&&!String.IsNullOrEmpty(s.QuestId))){var q=data.dofus.capturedQuests.FirstOrDefault(x=>x.character==c.id&&Same(x.id,x.name,step.QuestId,step.Title));if(q==null)continue;var p=DofusCompanion.Get(data,new DofusCharacter{id=c.id,guide=doc.Slug});if(p.done.Contains(step.Key))continue;p.done.Add(step.Key);var batch=data.dofus.captureHistory.FirstOrDefault(b=>b.id==q.batch);if(batch!=null&&!batch.marks.Any(m=>m.guide==doc.Slug&&m.step==step.Key))batch.marks.Add(new CaptureMark{guide=doc.Slug,step=step.Key,questId=step.QuestId,name=step.Title});}}
 internal static int Commit(Store store,string character,List<CaptureQuestChoice> choices,CaptureCatalogue catalogue){if(!store.Value.dofus.characters.Any(c=>c.id==character))throw new InvalidOperationException("Le personnage n’existe plus.");if(choices.Count==0||choices.Count>500)throw new InvalidOperationException("Sélectionnez de 1 à 500 quêtes.");if(choices.Any(q=>!catalogue.Quests.Any(x=>x.Id==q.Id&&x.Name==q.Name)))throw new InvalidOperationException("Quête absente du catalogue vérifié.");int count=0;PersonalWorkflows.Change(store,()=>{var batch=new QuestCaptureBatch{id=Guid.NewGuid().ToString("N"),character=character,date=DateTime.Now.ToString("yyyy-MM-dd HH:mm")};foreach(var q in choices){if(Done(store.Value,character,q.Id,q.Name))continue;store.Value.dofus.capturedQuests.Add(new CapturedQuest{character=character,id=q.Id,name=q.Name,batch=batch.id});count++;}if(count==0)return;batch.count=count;store.Value.dofus.captureHistory.Add(batch);while(store.Value.dofus.captureHistory.Count>30)store.Value.dofus.captureHistory.RemoveAt(0);var c=store.Value.dofus.characters.First(x=>x.id==character);foreach(var doc in catalogue.Documents)Apply(store.Value,doc,c);});return count;}
 internal static bool Undo(Store store,string character){var batch=store.Value.dofus.captureHistory.LastOrDefault(b=>b.character==character);if(batch==null)return false;PersonalWorkflows.Change(store,()=>{foreach(var m in batch.marks){var p=store.Value.dofus.progress.FirstOrDefault(x=>x.characterId==character&&x.guide==m.guide);if(p!=null)p.done.Remove(m.step);}store.Value.dofus.capturedQuests.RemoveAll(q=>q.batch==batch.id);store.Value.dofus.captureHistory.Remove(batch);});return true;}
 internal static void Remove(Data data,string character,string id,string name){foreach(var b in data.dofus.captureHistory.Where(b=>b.character==character)){foreach(var m in b.marks.Where(m=>Same(m.questId,m.name,id,name)).ToList()){var p=data.dofus.progress.FirstOrDefault(p0=>p0.characterId==character&&p0.guide==m.guide);if(p!=null)p.done.Remove(m.step);b.marks.Remove(m);}}data.dofus.capturedQuests.RemoveAll(q=>q.character==character&&Same(q.id,q.name,id,name));}
 internal static void Keep(Data data,string character,string id,string name){foreach(var b in data.dofus.captureHistory.Where(b=>b.character==character))b.marks.RemoveAll(m=>Same(m.questId,m.name,id,name));data.dofus.capturedQuests.RemoveAll(q=>q.character==character&&Same(q.id,q.name,id,name));}
 // A later explicit manual validation takes ownership of the step.
 internal static void Manual(Data data,string character,TougliDocument doc,TougliStep step,bool complete){foreach(var b in data.dofus.captureHistory.Where(b=>b.character==character))b.marks.RemoveAll(m=>m.guide==doc.Slug&&m.step==step.Key);if(!complete&&!String.IsNullOrEmpty(step.QuestId))Remove(data,character,step.QuestId,step.Title);}
 internal static void Test(string folder){var store=new Store(Path.Combine(folder,"qi"));var c=new DofusCharacter{id="a",name="Test",guide="test-guide"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;var q=new CaptureQuestChoice{Id="123",Name="L’œuf oublié"};var doc=new TougliDocument{Slug=c.guide,Steps=new List<TougliStep>{new TougliStep{Key="a",QuestId="123",Title=q.Name},new TougliStep{Key="note",Title=q.Name}}};var cat=new CaptureCatalogue{Quests=new List<CaptureQuestChoice>{q},Documents=new List<TougliDocument>{doc}};if(Exact(cat,"L'oeuf oublie").Count!=1||Exact(cat,"L'œuf oublie et autre").Count!=0||Suggestions(cat,"L'oeuf oubliee").Count!=1)throw new Exception("Correspondances OCR");Commit(store,c.id,new List<CaptureQuestChoice>{q,q},cat);if(store.Value.dofus.capturedQuests.Count!=1||Done(store.Value,"b",q.Id,q.Name)||DofusCompanion.Find(store.Value,c).done.Count!=1)throw new Exception("Isolation ou doublon import");var loaded=new Store(store.Root);var future=new TougliDocument{Slug="autre-guide",Steps=new List<TougliStep>{new TougliStep{Key="future",QuestId=q.Id,Title=q.Name}}};Apply(loaded.Value,future,c);loaded.Save();Undo(loaded,c.id);if(Done(loaded.Value,c.id,q.Id,q.Name)||loaded.Value.dofus.progress.Any(p=>p.done.Count>0))throw new Exception("Annulation import futur");DofusCompanion.Get(store.Value,c).done.Add("preexisting");Undo(store,c.id);if(!DofusCompanion.Find(store.Value,c).done.Contains("preexisting"))throw new Exception("Progression antérieure perdue");Commit(store,c.id,new List<CaptureQuestChoice>{q},cat);Manual(store.Value,c.id,doc,doc.Steps[0],true);Undo(store,c.id);if(!DofusCompanion.Find(store.Value,c).done.Contains("a"))throw new Exception("Validation manuelle perdue");var conflict=new CaptureCatalogue{Quests=new List<CaptureQuestChoice>{q,new CaptureQuestChoice{Id="456",Name=q.Name}}};if(Exact(conflict,q.Name).Count!=2)throw new Exception("Ambiguïté masquée");var before=store.Value.dofus.capturedQuests.Count;Directory.CreateDirectory(Path.Combine(store.Root,"state.json.tmp"));bool failed=false;try{Commit(store,c.id,new List<CaptureQuestChoice>{q},cat);}catch(IOException){failed=true;}catch(UnauthorizedAccessException){failed=true;}finally{Directory.Delete(Path.Combine(store.Root,"state.json.tmp"));}if(!failed||store.Value.dofus.capturedQuests.Count!=before)throw new Exception("Retour arrière après échec d’écriture");File.WriteAllText(Path.Combine(folder,"QUEST_IMPORT_PASS.txt"),"PASS: exact and approximate matching, ambiguous names, deduplication, character isolation, persisted ledger, future guides, targeted undo, prior/manual progress preserved, failed-save rollback.");}
}
